@@ -2,10 +2,14 @@ package org.jsoup.select;

 import org.jsoup.helper.Validate;
 import org.jsoup.nodes.Element;
+import org.jsoup.nodes.Node;
+import org.jsoup.nodes.TextNode;
+import org.jsoup.nodes.PseudoTextElement;

 import java.util.ArrayList;
 import java.util.Collection;
 import java.util.IdentityHashMap;
+import java.util.List;

 /**
  * CSS-like element selector, that finds elements matching a query.
@@ -101,9 +105,121 @@ public class Selector {
     public static Elements select(Evaluator evaluator, Element root) {
         Validate.notNull(evaluator);
         Validate.notNull(root);
+        if (hasMatchText(evaluator)) {
+            return collectWithMatchText(evaluator, root);
+        }
         return Collector.collect(evaluator, root);
     }

+    private static boolean hasMatchText(Evaluator evaluator) {
+        if (evaluator instanceof Evaluator.MatchText) {
+            return true;
+        }
+        if (evaluator instanceof CombiningEvaluator) {
+            CombiningEvaluator ce = (CombiningEvaluator) evaluator;
+            for (Evaluator e : ce.evaluators) {
+                if (hasMatchText(e)) {
+                    return true;
+                }
+            }
+        }
+        return false;
+    }
+
+    private static Elements collectWithMatchText(Evaluator evaluator, Element root) {
+        Evaluator baseEvaluator = extractBaseEvaluator(evaluator);
+        Elements baseElements = Collector.collect(baseEvaluator, root);
+
+        Elements result = new Elements();
+        for (Element el : baseElements) {
+            wrapTextNodes(el, result);
+        }
+
+        Evaluator textFilterEvaluator = extractTextFilterEvaluator(evaluator);
+        if (!(textFilterEvaluator instanceof Evaluator.AllElements)) {
+            Elements filtered = new Elements();
+            for (Element el : result) {
+                if (textFilterEvaluator.matches(root, el)) {
+                    filtered.add(el);
+                }
+            }
+            return filtered;
+        }
+        return result;
+    }
+
+    private static Evaluator extractBaseEvaluator(Evaluator evaluator) {
+        if (evaluator instanceof Evaluator.MatchText) {
+            return new Evaluator.AllElements();
+        }
+        if (evaluator instanceof CombiningEvaluator.And) {
+            CombiningEvaluator ce = (CombiningEvaluator) evaluator;
+            List<Evaluator> newEvals = new java.util.ArrayList<>();
+            for (Evaluator e : ce.evaluators) {
+                if (!hasMatchText(e)) {
+                    newEvals.add(e);
+                }
+            }
+            if (newEvals.isEmpty()) {
+                return new Evaluator.AllElements();
+            } else if (newEvals.size() == 1) {
+                return newEvals.get(0);
+            } else {
+                return new CombiningEvaluator.And(newEvals);
+            }
+        }
+        return evaluator;
+    }
+
+    private static Evaluator extractTextFilterEvaluator(Evaluator evaluator) {
+        if (evaluator instanceof Evaluator.MatchText) {
+            return new Evaluator.AllElements();
+        }
+        if (evaluator instanceof CombiningEvaluator.And) {
+            CombiningEvaluator ce = (CombiningEvaluator) evaluator;
+            List<Evaluator> newEvals = new java.util.ArrayList<>();
+            for (Evaluator e : ce.evaluators) {
+                if (e instanceof Evaluator.MatchText || isTextPseudoSelector(e)) {
+                    if (!(e instanceof Evaluator.MatchText)) {
+                        newEvals.add(e);
+                    }
+                }
+            }
+            if (newEvals.isEmpty()) {
+                return new Evaluator.AllElements();
+            } else if (newEvals.size() == 1) {
+                return newEvals.get(0);
+            } else {
+                return new CombiningEvaluator.And(newEvals);
+            }
+        }
+        return new Evaluator.AllElements();
+    }
+
+    private static boolean isTextPseudoSelector(Evaluator e) {
+        return e instanceof Evaluator.IsFirstChild || e instanceof Evaluator.IsLastChild ||
+               e instanceof Evaluator.IsFirstOfType || e instanceof Evaluator.IsLastOfType ||
+               e instanceof Evaluator.IsOnlyChild || e instanceof Evaluator.IsOnlyOfType;
+    }
+
+    private static void wrapTextNodes(Element el, Elements elements) {
+        List<Node> textNodes = new java.util.ArrayList<>();
+        for (Node node : el.childNodes()) {
+            if (node instanceof TextNode) {
+                String text = ((TextNode) node).getWholeText().trim();
+                if (text.length() > 0) {
+                    textNodes.add(node);
+                }
+            }
+        }
+        for (Node node : textNodes) {
+            TextNode textNode = (TextNode) node;
+            PseudoTextElement pseudo = new PseudoTextElement(textNode.getWholeText().trim());
+            textNode.replaceWith(pseudo);
+            elements.add(pseudo);
+        }
+    }
+
